{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.slick_inv_report as WITH inv_sent AS ( SELECT UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) AS sku_group, TO_DATE(TRIM(_AB_ADDITIONAL_PROPERTIES:\"Date \"), \'DD-MM-YYYY\') AS inward_date, sum(TRY_TO_NUMBER(TRIM(_AB_ADDITIONAL_PROPERTIES:\"Qty Sent \"))) AS qty_sent FROM snitch_db.maplemonk.S3_SLIKK_inventory group by 1,2 ), min_dates AS ( SELECT UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) AS sku_group, MIN(TO_DATE(TRIM(_AB_ADDITIONAL_PROPERTIES:\"Date \"), \'DD-MM-YYYY\')) AS first_inward_date FROM snitch_db.maplemonk.S3_SLIKK_inventory GROUP BY 1 ), date_expanded AS ( SELECT m.sku_group, DATEADD(DAY, s.seq, m.first_inward_date) AS generated_date FROM min_dates m, LATERAL ( SELECT SEQ4() AS seq FROM TABLE(GENERATOR(ROWCOUNT => 10000)) ) s WHERE DATEADD(DAY, s.seq, m.first_inward_date) <= CURRENT_DATE() ), main_data as ( SELECT sku_group, generated_date as date FROM date_expanded ORDER BY sku_group, generated_date ), outward as ( SELECT UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) AS sku_group, TO_DATE(TRIM(t._AB_ADDITIONAL_PROPERTIES:\"Date \"), \'DD-MM-YYYY\') AS outward_date, sum(TRIM(t._AB_ADDITIONAL_PROPERTIES:\"Pullback Inv \")::int) AS Pullback_Inventory FROM snitch_db.maplemonk.S3_SLIKK_PULLBACK AS t group by 1,2 ), sales as ( SELECT case when upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-05-SHIRT\' then \'4MSN1310-05\' when upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-02-SHIRT\' then \'4MSN1310-02\' when upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-08-SHIRT\' then \'4MSN1310-08\' else upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) end as sku_group, to_date(order_date,\'DD-MM-YYYY\') as sale_date, sum(total_quantity) as total_quantity, from snitch_db.maplemonk.S3_SLIKK_SALES group by 1,2 ), returns as ( SELECT case when upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-05- SHIRT\' then \'4MSN1310-05\' when upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-02-SHIRT\' then \'4MSN1310-02\' when upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) = \'4MSN1310-08-SHIRT\' then \'4MSN1310-08\' else upper(trim(REVERSE(SUBSTRING(REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku))))) end as sku_group, to_date(create_date,\'DD-MM-YYYY\') as return_date, sum(quantity) as return_qty from snitch_db.maplemonk.S3_SLIKK_RETURNS where status != \'CANCELLED\' group by 1,2 ), main_data2 as ( select a.date, a.sku_group, ifnull(b.Pullback_Inventory,0) as Pullback_Inventory, ifnull(c.total_quantity,0) as sales_quantity, ifnull(d.return_qty,0) as return_qty, ifnull(e.qty_sent,0) as qty_sent from main_data a left join outward b on a.sku_group = b.sku_group and a.date = b.outward_date left join sales c on a.sku_group = c.sku_group and a.date = c.sale_date left join returns d on a.sku_group = d.sku_group and a.date = d.return_date left join inv_sent e on a.sku_group = e.sku_group and a.date = e.inward_date ), first_send_inv as ( select sku_group, min(date) as first_send_date from main_data2 group by 1 ), final_pre as ( select a.*, b.first_send_date from main_data2 a left join first_send_inv b on a.sku_group = b.sku_group ), inventory_calc AS ( SELECT date, sku_group, Pullback_Inventory, sales_quantity, return_qty, qty_sent, first_send_date, CAST(qty_sent AS NUMBER) AS closing_inventory FROM final_pre WHERE date = first_send_date UNION ALL SELECT curr.date, curr.sku_group, curr.Pullback_Inventory, curr.sales_quantity, curr.return_qty, curr.qty_sent, curr.first_send_date, CAST( prev.closing_inventory - curr.Pullback_Inventory - curr.sales_quantity + curr.return_qty + curr.qty_sent AS NUMBER ) AS closing_inventory FROM inventory_calc prev JOIN final_pre curr ON curr.sku_group = prev.sku_group AND curr.date = DATEADD(DAY, 1, prev.date) ), prod_pre as ( SELECT ic.date, ic.sku_group, ic.Pullback_Inventory, ic.sales_quantity, ic.first_send_date, ic.return_qty, ic.qty_sent, coalesce(LAG(ic.closing_inventory) OVER (PARTITION BY ic.sku_group ORDER BY ic.date),closing_inventory) AS opening_inventory, ic.closing_inventory FROM inventory_calc ic ORDER BY ic.sku_group, ic.date ), prod_details as ( select sku_group, product_name, sku_class, category, title, print_design, collar_new, material_new, fit, color, sleeve_type from snitch_db.maplemonk.metafields_data qualify row_number() over (partition by sku_group order by status desc) = 1 ) select a.*, product_name, sku_class, case when category is null then \'Shirts\' else category end as category, title, print_design, collar_new, material_new, fit, color, sleeve_type from prod_pre a left join prod_details b on a.sku_group = b.sku_group ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            